"use client";

import { forwardRef, useEffect, useId, useRef, useState } from "react";
import type { ReactNode } from "react";
import Image from "next/image";
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react";
import type { Variants } from "motion/react";
import { ArrowRight, ArrowUpRight, Check, Share } from "lucide-react";
import { AnimatedCounter } from "@/registry/components/animated-counter/animated-counter";
import { Avatar } from "@/registry/components/avatar/avatar";
import { Button } from "@/registry/components/button/button";
import { CopyButton } from "@/registry/components/copy-button/copy-button";
import SegmentedControl from "@/registry/components/segmented-control/segmented-control";
import { Switch } from "@/registry/components/switch/switch";
import { motionTokens } from "@/lib/motion-tokens";
import { person, photo } from "@/lib/media";
import styles from "./hero-section.module.css";

export type HeroSectionVariant = "centered" | "split" | "minimal";

export interface HeroAction {
  label: string;
  href?: string;
  onClick?: () => void;
  /** Opens in a new tab and shows an outward arrow. */
  external?: boolean;
}

export interface HeroInstallCommand {
  /** Short tab label, such as npm or pnpm. */
  label: string;
  command: string;
}

export interface HeroSectionProps {
  /** `centered` with an install command, `split` beside a product visual, or `minimal` text only. */
  variant?: HeroSectionVariant;
  /** A short link above the title for a real announcement. Pass null to hide it. */
  announcement?: HeroAction | null;
  title?: string;
  /** A phrase inside `title` drawn in the brand ink gradient. */
  highlight?: string;
  description?: string;
  primaryAction?: HeroAction | null;
  secondaryAction?: HeroAction | null;
  /** Package manager commands for the centered variant. Pass null to hide the command. */
  install?: HeroInstallCommand[] | null;
  /** Initial install tab when uncontrolled. */
  defaultInstall?: string;
  /** Selected install tab (controlled). */
  installValue?: string;
  onInstallChange?: (label: string) => void;
  /** The visual for the split variant. Defaults to a live Arc composition. */
  media?: ReactNode;
  /** Small facts under the minimal variant, such as the version and license. */
  meta?: string[];
  /** Plays the entrance once on mount. Defaults to true. */
  animateIn?: boolean;
  className?: string;
}

type Bezier = [number, number, number, number];
const enter = [...motionTokens.ease.enter] as Bezier;

const exampleInstall: HeroInstallCommand[] = [
  { label: "npm", command: "npx shadcn@latest add @uiarc/hero-section" },
  { label: "pnpm", command: "pnpm dlx shadcn@latest add @uiarc/hero-section" },
  { label: "bun", command: "bunx --bun shadcn@latest add @uiarc/hero-section" },
];

/** Children rise out of a soft blur, one after another, once. */
const group: Variants = { hidden: {}, shown: { transition: { staggerChildren: .07, delayChildren: .04 } } };
const rise: Variants = {
  hidden: { opacity: 0, y: 14, filter: `blur(${motionTokens.blur.soft}px)` },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: .7, ease: enter } },
};
const fade: Variants = { hidden: { opacity: 0 }, shown: { opacity: 1, transition: { duration: .3 } } };

function ActionLink({ action, kind }: { action: HeroAction; kind: "primary" | "secondary" | "text" }) {
  const cls = `${styles.action} ${styles[kind]}`;
  const icon = action.external ? <ArrowUpRight size={16} strokeWidth={1.75} aria-hidden="true" /> : kind === "text" || kind === "primary" ? <ArrowRight className={styles.arrow} size={16} strokeWidth={1.75} aria-hidden="true" /> : null;
  if (action.href) return <a className={cls} href={action.href} onClick={action.onClick} {...(action.external ? { target: "_blank", rel: "noopener noreferrer" } : {})}>{action.label}{icon}</a>;
  return <button type="button" className={cls} onClick={action.onClick}>{action.label}{icon}</button>;
}

function Title({ title, highlight, id }: { title: string; highlight?: string; id: string }) {
  const at = highlight ? title.indexOf(highlight) : -1;
  if (!highlight || at < 0) return <h1 id={id} className={styles.title}>{title}</h1>;
  return <h1 id={id} className={styles.title}>{title.slice(0, at)}<span className={styles.highlight}>{highlight}</span>{title.slice(at + highlight.length)}</h1>;
}

/** A terminal line with a gliding package manager switch and a copy button whose width never changes. */
function InstallCommand({ commands, value, onChange, reduced }: { commands: HeroInstallCommand[]; value: string; onChange: (label: string) => void; reduced: boolean }) {
  const id = useId();
  const active = commands.find(item => item.label === value) ?? commands[0];
  return <div className={styles.install}>
    <LayoutGroup id={id}>
      <div className={styles.installTabs} role="group" aria-label="Package manager">
        {commands.map(item => <button key={item.label} type="button" className={styles.installTab} aria-pressed={item.label === active.label} onClick={() => onChange(item.label)}>
          {item.label === active.label && <motion.span layoutId="tab" className={styles.installHighlight} transition={reduced ? { duration: 0 } : motionTokens.spring.morph} aria-hidden="true" />}
          <span>{item.label}</span>
        </button>)}
      </div>
    </LayoutGroup>
    <div className={styles.installLine}>
      <span className={styles.prompt} aria-hidden="true">$</span>
      <span className={styles.commandSlot}>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.code key={active.label} className={styles.command}
            initial={reduced ? { opacity: 0 } : { opacity: 0, y: 6, filter: `blur(${motionTokens.blur.subtle}px)` }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: -6, filter: `blur(${motionTokens.blur.subtle}px)`, transition: { duration: .12 } }}
            transition={reduced ? { duration: 0 } : { y: motionTokens.spring.snappy, opacity: { duration: .18 }, filter: { duration: .18 } }}>
            {active.command}
          </motion.code>
        </AnimatePresence>
      </span>
      <CopyButton value={active.command} label="Copy install command" iconOnly variant="plain" className={styles.copy} />
    </div>
  </div>;
}

const periods = [{ value: "week", label: "Week" }, { value: "month", label: "Month" }, { value: "year", label: "Year" }];
const focusHours: Record<string, number> = { week: 18.5, month: 74, year: 812 };
const emma = person("emma-collins");
const office = photo("home-office");

/** The default split visual: a photo with a live card built from Arc components, so every control in it works. */
export function HeroShowcase() {
  const [available, setAvailable] = useState(true);
  const [period, setPeriod] = useState("week");
  const [shared, setShared] = useState(false);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  return <div className={styles.showcase}>
    <div className={styles.showcasePhoto}><Image src={office.src} alt={office.alt} fill sizes="(max-width: 760px) 100vw, 560px" priority={false} /></div>
    <div className={styles.showcaseCard}>
      <div className={styles.cardHead}>
        <Avatar name={emma.name} src={emma.src} size="md" status={available ? "online" : "offline"} />
        <div className={styles.cardWho}><span>{emma.name}</span><span>{available ? "Available for reviews" : "Heads down"}</span></div>
        <Switch aria-label="Available for reviews" checked={available} onCheckedChange={setAvailable} />
      </div>
      <SegmentedControl label="Period" options={periods} value={period} onValueChange={setPeriod} />
      <div className={styles.cardStat}>
        <AnimatedCounter value={focusHours[period]} decimals={period === "week" ? 1 : 0} suffix=" h" />
        <span>Focus time this {period}</span>
      </div>
      <Button variant="secondary" size="sm" onClick={() => { setShared(true); window.clearTimeout(timer.current); timer.current = window.setTimeout(() => setShared(false), 1800); }}>
        {shared ? <><Check size={15} strokeWidth={2.25} aria-hidden="true" />Report shared</> : <><Share size={15} strokeWidth={1.75} aria-hidden="true" />Share report</>}
      </Button>
    </div>
  </div>;
}

/**
 * A landing page hero in three layouts. Content rises in once, in reading order; the centered layout carries an install
 * command with a gliding package manager switch, the split layout sits beside a live product visual, and the minimal one
 * is type alone.
 */
export const HeroSection = forwardRef<HTMLElement, HeroSectionProps>(function HeroSection({
  variant = "centered",
  announcement = { label: "Site blocks are here: headers, footers, and heroes" },
  title = "Interfaces that move with intent",
  highlight = "move with intent",
  description = "Arc is a library of React components and blocks with motion that explains every change. Copy the source, keep full control.",
  primaryAction = { label: "Get started" },
  secondaryAction = { label: "Browse components" },
  install = exampleInstall,
  defaultInstall,
  installValue,
  onInstallChange,
  media,
  meta = ["Version 2.4", "140 components", "Light and dark"],
  animateIn = true,
  className,
}, ref) {
  const id = useId();
  const reduced = !!useReducedMotion();
  const [innerInstall, setInnerInstall] = useState(defaultInstall ?? install?.[0]?.label ?? "");
  const currentInstall = installValue ?? innerInstall;
  const item = reduced ? fade : rise;
  const setInstall = (label: string) => { if (installValue === undefined) setInnerInstall(label); onInstallChange?.(label); };

  const announcementNode = announcement && <motion.div variants={item} className={styles.announcementRow}>
    {announcement.href
      ? <a className={styles.announcement} href={announcement.href} onClick={announcement.onClick}>{announcement.label}<ArrowRight className={styles.arrow} size={14} strokeWidth={2} aria-hidden="true" /></a>
      : <button type="button" className={styles.announcement} onClick={announcement.onClick}>{announcement.label}<ArrowRight className={styles.arrow} size={14} strokeWidth={2} aria-hidden="true" /></button>}
  </motion.div>;
  const actions = (primaryAction || secondaryAction) && <motion.div variants={item} className={styles.actions}>
    {primaryAction && <ActionLink action={primaryAction} kind={variant === "minimal" ? "text" : "primary"} />}
    {secondaryAction && <ActionLink action={secondaryAction} kind={variant === "minimal" ? "text" : "secondary"} />}
  </motion.div>;

  return <section ref={ref} className={[styles.hero, styles[variant], className].filter(Boolean).join(" ")} aria-labelledby={`${id}-title`}><div className={styles.inner}>
    <motion.div className={styles.copy} variants={group} initial={animateIn ? "hidden" : false} animate="shown">
      {variant !== "minimal" && announcementNode}
      <motion.div variants={item}><Title id={`${id}-title`} title={title} highlight={variant === "minimal" ? undefined : highlight} /></motion.div>
      {description && <motion.p variants={item} className={styles.description}>{description}</motion.p>}
      {actions}
      {variant === "centered" && install && install.length > 0 && <motion.div variants={item} className={styles.installWrap}>
        <InstallCommand commands={install} value={currentInstall} onChange={setInstall} reduced={reduced} />
      </motion.div>}
      {variant === "minimal" && meta.length > 0 && <motion.ul variants={item} className={styles.meta}>{meta.map(entry => <li key={entry}>{entry}</li>)}</motion.ul>}
    </motion.div>
    {variant === "split" && <motion.div className={styles.media}
      initial={animateIn ? (reduced ? { opacity: 0 } : { opacity: 0, y: 20, scale: .985 }) : false}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={reduced ? { duration: .3 } : { duration: .9, ease: enter, delay: .18 }}>
      {media ?? <HeroShowcase />}
    </motion.div>}
  </div></section>;
});

HeroSection.displayName = "HeroSection";

const variantOptions = [{ value: "centered", label: "Centered" }, { value: "split", label: "Split" }, { value: "minimal", label: "Minimal" }];

/** Preview: the hero with a switch between its layouts. Switching replays the entrance. */
export function HeroSectionBlock({ variant: initial = "centered" }: { variant?: HeroSectionVariant }) {
  const [variant, setVariant] = useState<HeroSectionVariant>(initial);
  const [last, setLast] = useState<string | null>(null);
  const report = (label: string) => () => setLast(label);
  return <div className={styles.preview}>
    <SegmentedControl label="Hero layout" options={variantOptions} value={variant} onValueChange={value => setVariant(value as HeroSectionVariant)} />
    <div className={styles.frame}>
      <HeroSection
        key={variant}
        variant={variant}
        announcement={{ label: "Site blocks are here: headers, footers, and heroes", onClick: report("the announcement") }}
        primaryAction={{ label: variant === "minimal" ? "Read the docs" : "Get started", onClick: report(variant === "minimal" ? "Read the docs" : "Get started") }}
        secondaryAction={variant === "minimal" ? { label: "View on GitHub", external: true, onClick: report("View on GitHub") } : { label: "Browse components", onClick: report("Browse components") }}
      />
    </div>
    <p className={styles.srOnly} aria-live="polite">{last ? `Opened ${last}` : ""}</p>
  </div>;
}

export default HeroSectionBlock;

.hero { position: relative; isolation: isolate; container: hero / inline-size; overflow: hidden; background: var(--background); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
/* One faint wash of the brand gradient behind the centered layout, fading out before the command. */
.centered::before { position: absolute; z-index: -1; inset: 0 0 35%; background: var(--arc-gradient-soft); content: ""; -webkit-mask-image: linear-gradient(to bottom, #000, transparent); mask-image: linear-gradient(to bottom, #000, transparent); }

.inner { padding: var(--space-24) var(--space-6); }
.copy { display: grid; grid-template-columns: minmax(0, 1fr); justify-items: center; gap: var(--space-5); max-width: 760px; margin: 0 auto; text-align: center; }
.title { margin: 0; font-family: var(--font-display); font-size: clamp(2.25rem, 1.1rem + 5.4cqi, 4.5rem); font-weight: 500; letter-spacing: var(--tracking-display); line-height: 1.04; text-wrap: balance; }
.highlight { background: var(--arc-gradient-ink); -webkit-background-clip: text; background-clip: text; color: transparent; -webkit-box-decoration-break: clone; box-decoration-break: clone; }
.description { max-width: 560px; margin: 0; color: var(--text-secondary); font-size: var(--text-lg); line-height: 1.5; text-wrap: pretty; }

.announcementRow { display: flex; min-width: 0; max-width: 100%; }
.announcement { display: inline-flex; min-width: 0; max-width: 100%; min-height: 32px; align-items: center; gap: 6px; border: 1px solid var(--border); border-radius: var(--radius-pill); padding: 4px var(--space-3); background: var(--surface); color: var(--text-secondary); font: inherit; font-size: var(--text-sm); text-align: left; text-decoration: none; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard); }
.arrow { flex: none; transition: transform var(--duration-fast) var(--ease-standard); }

.actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3); margin-top: var(--space-1); }
.action { display: inline-flex; height: var(--control-height-md); align-items: center; justify-content: center; gap: var(--space-2); border: 1px solid transparent; border-radius: var(--radius-control); padding: 0 var(--space-5); font: inherit; font-size: var(--text-sm); font-weight: 500; text-decoration: none; white-space: nowrap; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: transform var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard), opacity var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.action:active { transform: scale(.97); }
.primary { background: var(--foreground); color: var(--background); }
.secondary { border-color: var(--border); background: var(--surface); color: var(--foreground); }
.text { height: auto; padding: var(--space-1) 0; background: none; color: var(--foreground); }
@media (hover: hover) and (pointer: fine) {
  .primary:hover { opacity: .9; }
  .secondary:hover { background: var(--surface-muted); }
  .text:hover { color: var(--text-secondary); }
  .announcement:hover { border-color: var(--border-strong); color: var(--foreground); }
  :is(.action, .announcement):hover .arrow { transform: translateX(2px); }
}

/* Install command */
.installWrap { width: min(100%, 540px); margin-top: var(--space-3); }
.install { overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); text-align: left; box-shadow: var(--shadow-resting); }
.installTabs { display: flex; gap: 2px; border-bottom: 1px solid var(--border-subtle); padding: 6px; }
.installTab { position: relative; isolation: isolate; height: 28px; border: 0; border-radius: 10px; padding: 0 10px; background: none; color: var(--text-muted); font: inherit; font-size: var(--text-xs); font-weight: 500; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard); }
.installTab[aria-pressed="true"] { color: var(--foreground); }
@media (hover: hover) and (pointer: fine) { .installTab:hover { color: var(--foreground); } }
.installHighlight { position: absolute; z-index: -1; inset: 0; border-radius: inherit; background: var(--surface-muted); }
.installLine { display: flex; align-items: center; gap: var(--space-3); padding: 6px 6px 6px var(--space-4); font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, monospace); font-size: 13px; }
.prompt { color: var(--text-muted); }
.commandSlot { position: relative; display: flex; min-width: 0; flex: 1; overflow-x: auto; scrollbar-width: none; }
.commandSlot::-webkit-scrollbar { display: none; }
.command { display: block; color: var(--foreground); font: inherit; white-space: nowrap; }
.copy { flex: none; }

/* Split */
.split .inner { display: grid; max-width: 1200px; grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr); align-items: center; gap: var(--space-12); margin: 0 auto; padding-inline: var(--space-10); }
.split .copy { max-width: none; margin: 0; justify-items: start; text-align: left; }
.split .actions { justify-content: flex-start; }
.media { min-width: 0; container: hero-media / inline-size; }
.showcase { position: relative; aspect-ratio: 5 / 4.4; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-surface); background: var(--surface-muted); }
.showcasePhoto { position: absolute; inset: 0; }
.showcasePhoto img { object-fit: cover; }
.showcaseCard { position: absolute; bottom: var(--space-5); left: var(--space-5); display: grid; width: min(300px, calc(100% - 40px)); gap: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: var(--space-4); background: var(--surface-raised); box-shadow: var(--shadow-floating); }
.cardHead { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: var(--space-3); }
.cardWho { display: grid; min-width: 0; }
.cardWho span:first-child { font-size: var(--text-sm); font-weight: 500; }
.cardWho span:last-child { overflow: hidden; color: var(--text-muted); font-size: var(--text-xs); text-overflow: ellipsis; white-space: nowrap; }
.cardStat { display: grid; gap: 2px; font-family: var(--font-display); font-size: var(--text-3xl); font-variant-numeric: tabular-nums; letter-spacing: var(--tracking-display); line-height: 1.1; }
.cardStat > span:last-child { font-family: var(--font-body); font-size: var(--text-xs); letter-spacing: var(--tracking-body); color: var(--text-muted); }

/* Minimal */
.minimal .inner { padding-inline: var(--space-10); }
.minimal .copy { max-width: 860px; margin: 0; justify-items: start; text-align: left; }
.minimal .actions { justify-content: flex-start; gap: var(--space-6); }
.meta { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); margin: var(--space-6) 0 0; border-top: 1px solid; border-image: var(--arc-gradient-line) 1; padding: var(--space-5) 0 0; color: var(--text-muted); font-size: var(--text-sm); list-style: none; }

@container hero (max-width: 800px) {
  .split .inner { grid-template-columns: minmax(0, 1fr); gap: var(--space-10); }
}
@container hero (max-width: 520px) {
  .inner, .split .inner, .minimal .inner { padding: var(--space-16) var(--space-5); }
  .description { font-size: var(--text-base); }
  .actions { width: 100%; }
  .actions .primary, .actions .secondary { flex: 1 1 auto; }
  .minimal .actions { gap: var(--space-2) var(--space-6); }
  .showcaseCard { padding: var(--space-3); }
  .cardHead { gap: var(--space-2); }
}
@container hero-media (max-width: 440px) {
  .showcase { display: grid; aspect-ratio: auto; overflow: visible; border: 0; background: none; }
  .showcasePhoto { position: relative; height: 200px; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); }
  .showcaseCard { position: relative; bottom: auto; left: auto; width: auto; margin: -56px var(--space-3) 0; }
}

.preview { display: grid; width: 100%; justify-items: center; gap: var(--space-4); }
.frame { width: 100%; overflow: hidden; border: 1px solid var(--border); border-radius: 20px; background: var(--background); }
.previewNote { min-height: 20px; margin: 0; color: var(--text-muted); font-size: var(--text-xs); }

@media (prefers-reduced-motion: reduce) {
  .action, .announcement, .arrow, .installTab { transition: none; }
  .action:active { transform: none; }
}

.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/**
 * Shared demo media. Files live in `public/media/`, credits in `public/media/CREDITS.md`.
 * Portraits are 400 px squares; photos are 1600 px on the long side.
 */

export interface MediaPerson {
  id: string;
  name: string;
  role?: string;
  src: string;
}

export interface MediaPhoto {
  id: string;
  alt: string;
  src: string;
  width: number;
  height: number;
}

export const people = [
  { id: "emma-collins", name: "Emma Collins", role: "Product designer", src: "/media/people/emma-collins.jpg" },
  { id: "marcus-johnson", name: "Marcus Johnson", role: "Frontend engineer", src: "/media/people/marcus-johnson.jpg" },
  { id: "jasmine-brooks", name: "Jasmine Brooks", role: "Design lead", src: "/media/people/jasmine-brooks.jpg" },
  { id: "olivia-bennett", name: "Olivia Bennett", role: "Platform engineer", src: "/media/people/olivia-bennett.jpg" },
  { id: "sofia-ramirez", name: "Sofia Ramirez", role: "Operations lead", src: "/media/people/sofia-ramirez.jpg" },
  { id: "ryan-sullivan", name: "Ryan Sullivan", role: "Account executive", src: "/media/people/ryan-sullivan.jpg" },
  { id: "hannah-walsh", name: "Hannah Walsh", role: "Customer success", src: "/media/people/hannah-walsh.jpg" },
  { id: "chloe-nguyen", name: "Chloe Nguyen", role: "Data analyst", src: "/media/people/chloe-nguyen.jpg" },
  { id: "ava-mitchell", name: "Ava Mitchell", role: "Marketing manager", src: "/media/people/ava-mitchell.jpg" },
  { id: "daniel-kim", name: "Daniel Kim", role: "Backend engineer", src: "/media/people/daniel-kim.jpg" },
  { id: "jordan-reyes", name: "Jordan Reyes", role: "Support specialist", src: "/media/people/jordan-reyes.jpg" },
  { id: "mateo-alvarez", name: "Mateo Alvarez", role: "Mobile engineer", src: "/media/people/mateo-alvarez.jpg" },
  { id: "tyler-hayes", name: "Tyler Hayes", role: "Sales lead", src: "/media/people/tyler-hayes.jpg" },
  { id: "andre-williams", name: "Andre Williams", role: "Finance partner", src: "/media/people/andre-williams.jpg" },
  { id: "nathan-cole", name: "Nathan Cole", role: "Engineering manager", src: "/media/people/nathan-cole.jpg" },
  { id: "diane-foster", name: "Diane Foster", role: "Chief operating officer", src: "/media/people/diane-foster.jpg" },
] as const satisfies readonly MediaPerson[];

export const photos = [
  { id: "lounge-chair", alt: "A woven oak lounge chair with a sheepskin and linen cushion on a concrete floor", src: "/media/photos/lounge-chair.jpg", width: 1280, height: 1600 },
  { id: "table-lamp", alt: "A white mushroom table lamp glowing beside books and a small vase", src: "/media/photos/table-lamp.jpg", width: 1600, height: 900 },
